def summarize_chip_yield(rows, required_items):
    chips = {}
    duplicates_ignored = 0
    missing_values = 0

    for row in rows:
        chip_id = row["chip_id"]
        test_item = row["test_item"]
        value = row["value"]
        unit = row["unit"]
        lower = row["lower"]
        upper = row["upper"]
        retest = int(row["retest"])

        if chip_id not in chips:
            chips[chip_id] = {}

        if test_item not in chips[chip_id]:
            chips[chip_id][test_item] = []

        existing_rows = chips[chip_id][test_item]
        for existing_row in existing_rows:
            if all(existing_row[key] == row[key] for key in row.keys() if key != "retest") and existing_row["retest"] >= retest:
                duplicates_ignored += 1
                break
        else:
            existing_rows.append({**row, "retest": retest})

    passed_chips = 0
    failed_chip_ids = []

    for chip_id, test_items in chips.items():
        if all(test_item in test_items and len(test_items[test_item]) > 0 for test_item in required_items):
            values = [float(row["value"]) / 1000 if row["unit"] == "mV" else float(row["value"]) for row in test_items.values()[0]]
            lower_values = [float(row["lower"]) / 1000 if row["unit"] == "mV" else float(row["lower"]) for row in test_items.values()[0]]
            upper_values = [float(row["upper"]) / 1000 if row["unit"] == "mV" else float(row["upper"]) for row in test_items.values()[0]]

            all_passed = True
            for value, lower, upper in zip(values, lower_values, upper_values):
                if not (lower <= value <= upper) or value == \":
                    all_passed = False
                    break

            if all_passed:
                passed_chips += 1
            else:
                failed_chip_ids.append(chip_id)
        else:
            failed_chip_ids.append(chip_id)

    yield_value = passed_chips / len(chips) if chips else 0.0

    return {
        "chips": len(chips),
        "passed_chips": passed_chips,
        "yield": round(yield_value, 4),
        "failed_chip_ids": sorted(failed_chip_ids),
        "duplicates_ignored": duplicates_ignored,
        "missing_values": missing_values,
    }
